const e=JSON.parse('{"studio":{"add_routine":"Добавить регулярное поручение","routine_title":"Название поручения","routine_task":"Что должен делать этот агент?","routine_hours":"Повторять каждые (часов)","routine_error":"Не удалось создать регулярное поручение.","eyebrow":"Студия агента","heading":"Настройте агента под себя.","subtitle":"Задайте, как он думает, работает и выглядит.","sections":"Настройки агента","profile":"Профиль","model":"Модель","appearance":"Внешний вид","limits":"Ограничения","activity":"Активность","profile_heading":"Чёткая роль и ваши инструкции.","model_heading":"Выберите, как он думает.","appearance_heading":"Придайте ему индивидуальность.","limits_heading":"Задайте границы.","activity_heading":"Работа, регулярные поручения и действия.","role":"Роль","role_placeholder":"За что отвечает этот агент?","instructions_placeholder":"Опишите его работу, приоритеты и то, как ему следует взаимодействовать с вами.","instructions_hint":"Эти инструкции направляют будущие задачи. Текущие предпочтения инструментов и правила подтверждения сохраняются.","tools_hint":"Доступ к инструментам зависит от ваших подключений и разрешений агента. В его чате можно изменить приоритеты или попросить новые возможности.","chat_action":"Открыть чат агента","preview_hint":"Изменения сразу видны на фигурке. Сохраните, когда результат вам понравится.","character":"Персонаж","imported":"Ваш импортированный персонаж","palette":"Цветовая палитра","shuffle":"Удивите меня","wardrobe":"Одежда и аксессуары","none":"Нет","reset_look":"Сбросить цвета и аксессуары","provider":"Провайдер","account":"Аккаунт","active_account":"Активный аккаунт","saved_account":"Сохранённый аккаунт","model_hint":"Выберите подключённого провайдера, модель и глубину рассуждения. Изменения модели сохраняются отдельно, разговор остаётся.","connect_hint":"Подключите провайдера в разделе «Агенты» или «API-ключи», чтобы менять его модель здесь.","save_model":"Применить модель","budget":"Дневной бюджет (USD)","budget_hint":"0 означает отсутствие лимита. Бюджет сбрасывается в полночь по UTC.","concurrency":"Параллельные задачи","concurrency_hint":"Максимальное число одновременно выполняемых задач.","ceiling_safe":"Разрешить только инструменты с уровнем «Безопасно».","ceiling_monitor":"Разрешить инструменты уровней «Безопасно» и «Под наблюдением».","ceiling_ask":"Также разрешить инструменты, требующие подтверждения.","invalid_limits":"Введите бюджет не меньше 0 и целое число задач не меньше 1.","spent_today":"Потрачено сегодня: ${amount}","total_spent":"Всего потрачено","notes":"Заметки вики","manage":"Управление агентом","recent":"Последняя активность","loading":"Загрузка активности…","no_activity":"Активности пока нет. Начните разговор, чтобы дать агенту первое поручение.","saved":"Изменения сохранены","unsaved":"Есть несохранённые изменения","ready":"Можно редактировать","save":"Сохранить изменения","discard":"Отменить","sample":"Только просмотр: демонстрационных агентов нельзя сохранить на сервере.","load_error":"Не удалось загрузить настройки.","retry":"Повторить","leave":"Отменить несохранённые изменения агента?","saving_wait":"Дождитесь завершения сохранения."},"world":{"talk_kind_query":"спрашивает","talk_kind_answer":"отвечает","talk_kind_propose":"предлагает","talk_digest":"ещё +{0}","talk_listening":"слушает","talk_calling":"вызывает {0}","talk_more":"…","hud_talking":"Говорят: {0}","room_round":"Раунд {0}/{1}","room_settled":"Комната закрыта","room_reason_message_cap":"всё сказано","room_reason_round_cap":"раунды закончились","room_reason_silence":"никто не говорил","room_reason_user":"закрыто вами","room_reason_kill_switch":"сообщество остановлено","mode_label":"Представление агентов","mode_world":"Мир","mode_ledger":"Список","hud_agents":"Агентов: {count}","hud_active":"Активных: {count}","sample_badge":"Демонстрационный состав","reduced_motion_note":"Сокращённое движение: остров неподвижен","controls_hint":"Перетаскивайте для перемещения · Правая кнопка — поворот · Прокрутка — масштаб · Стрелки — движение · Нажмите на здание, чтобы повернуть","rotate_hint":"Потяните ручку вокруг здания, чтобы повернуть его. Shift включает шаг 15°.","rotate_reset":"Вернуть исходное направление","rotate_reset_short":"Сбросить","rotate_reset_all":"Вернуть всем зданиям исходное направление","rotate_reset_all_count":"Сбросить поворот: {count}","zoom_label":"Масштаб","zoom_in":"Увеличить","zoom_out":"Уменьшить","compass_label":"Направление вида","turn_left":"Повернуть вид влево (Q)","turn_right":"Повернуть вид вправо (E)","view_reset":"Вернуть исходный вид (R)","minimap_label":"Карта острова — нажмите для перехода","webgl_missing_title":"Для острова нужен WebGL","webgl_missing_body":"Это окно сейчас не поддерживает отображение 3D. Те же агенты доступны в списке.","open_ledger":"Открыть список","loading":"Строим остров…","place_plugins":"Доки плагинов","place_foundry":"Мастерская агентов","drawer_foundry_title":"Мастерская агентов","drawer_foundry_hint":"Здесь создаются новые агенты. Каждый выходит из портала и едет по конвейеру к площади.","foundry_create":"Создать нового агента","foundry_population":"На острове живут агенты: {count}","foundry_recent":"Недавно созданные","foundry_none":"Агентов пока не создавали.","foundry_walkout":"Новый агент выходит из портала и находит своё место в поселении.","drawer_plugins_title":"Доки плагинов","drawer_plugins_hint":"Все установленные плагины, сгруппированные по типам. Агент приходит сюда, когда использует плагин в задаче.","drawer_open_section":"Открыть раздел «Плагины»","card_kind_building":"Здание","cli_group_seats":"Аккаунты для программирования","plugin_group_connected":"Подключённые","plugin_group_available":"Доступные","status_connected":"Подключён","status_available":"Не подключён","status_attention":"Требует внимания","status_installed":"Установлен","status_missing":"Не установлен","status_checking":"Проверяется","status_running":"Работает","status_stopped":"Остановлен","status_draft":"Черновик","status_ready":"Готов","card_does_title":"Назначение","card_how_title":"Как пользоваться","card_inside_title":"Что внутри сейчас","card_open_section":"Открыть раздел","card_create_agent":"Создать агента","card_drag_hint":"Перетаскивание — поворот · Колесо — масштаб · Двойное нажатие — сброс","card_reduced_motion":"Сокращённое движение: перетаскивайте для поворота","card_unavailable":"В этом окне невозможно отобразить здание.","card_plugins_does":"В доках плагинов находятся все установленные плагины, сгруппированные по типам: мозги, инструменты, речь, каналы, режим реального времени, слова пробуждения и исполнители. Агент приходит сюда, когда использует один из них.","card_plugins_how":"Устанавливайте и удаляйте плагины в разделе «Плагины». По умолчанию каждый агент может использовать их все. В чате агента укажите, какой плагин предпочесть.","card_foundry_does":"В мастерской создаются новые агенты. Новый агент выходит из портала и идёт к площади, чтобы присоединиться к команде.","card_foundry_how":"Создайте агента здесь или кнопкой «Новый» на панели агентов: укажите имя, должность, описание и аккаунт для работы. Всё остальное можно сообщить ему в собственном чате.","card_skills_does":"Кузница навыков хранит все известные приложению навыки: встроенные, ваши собственные и ещё не законченные черновики. Навык — повторно используемая процедура, которую агент запускает командой со слешем.","card_skills_how":"Создавайте и редактируйте навыки в разделе «Навыки»; агент также может подготовить черновик в чате. Черновик остаётся черновиком, пока вы его не одобрите.","card_mcp_does":"Башня связи подключается к серверам MCP приложения — внешним инструментам, которые может вызывать агент. Антенна вращается, пока агент обращается к серверу.","card_mcp_how":"Добавляйте и удаляйте серверы в разделе «MCP». Каждый агент имеет доступ ко всем подключённым серверам.","card_cli_does":"В терминальной таверне находятся CLI для программирования — Claude Code, Codex, Grok Build и другие — с входами по подписке. Агент сидит здесь за терминалом, пока выполняется сеанс программирования.","card_cli_how":"Подключите CLI или войдите по подписке в разделе «CLI». Тогда агент сможет работать через этот аккаунт вместо API-ключа.","card_archive_does":"Дом памяти — общая память команды: проверенные знания, личная память каждого агента и очередь на проверку. Агент приходит сюда, когда вспоминает или ищет сведения.","card_archive_how":"Читайте и приводите в порядок знания в разделе «Память». Предложенный агентом факт ждёт в очереди на проверку, пока вы его не примете.","drawer_close":"Закрыть","place_quests":"Доска поручений","hud_quests":"Поручения","quest_add_placeholder":"Новое поручение… Например, пять самых важных писем за сегодня","quest_wait_approval":"{agent} ждёт вашего подтверждения в своём чате — поручение начнётся сразу после него","quest_wait_busy":"{agent} занят — поручение начнётся, как только он освободится","quest_open_agent":"Открыть {agent}","quest_group_history":"История","drawer_quests_title":"Доска поручений","drawer_quests_hint":"Разместите поручение. Его возьмёт подходящий агент; если такого нет, мастерская создаст нового.","quest_compose_placeholder":"Что нужно сделать? Например: пять самых важных писем за сегодня","quest_compose_hint":"Ctrl+Enter — разместить","quest_post":"Разместить поручение","quest_posting":"Размещение…","quest_group_active":"На доске","quest_group_done":"Завершены","quest_group_failed":"С ошибкой","quest_group_cancelled":"Отменены","quest_empty":"Поручений пока нет. Разместите первое.","quest_state":{"open":"ожидает исполнителя","assigned":"назначено","running":"выполняется","done":"завершено","failed":"ошибка","cancelled":"отменено"},"quest_taken_by":"{agent} взял поручение","quest_forged":"{agent} создан для этого поручения","quest_no_taker":"Пока никто не смог взять поручение","quest_cancel":"Отменить","quest_retry":"Повторить","quest_result_label":"Передача результата","quest_open_label":"Ещё открыто","quest_refused":"Отклонено: {reason}","quest_age_now":"только что","quest_age_min":"{n} мин назад","quest_age_h":"{n} ч назад","quest_age_d":"{n} дн. назад","quest_close":"Закрыть","quest_loading":"Чтение доски…","quest_open_ledger":"Открыть список агентов","drawer_loading":"Чтение каталога плагинов…","drawer_empty":"Плагины не найдены.","plugin_group_brain":"Мозги","plugin_group_tool":"Инструменты","plugin_group_stt":"Распознавание речи","plugin_group_tts":"Синтез речи","plugin_group_channel":"Каналы","plugin_group_realtime":"Голос в реальном времени","plugin_group_wakeword":"Слова пробуждения","plugin_group_harness":"Исполнители","place_skills":"Кузница навыков","place_mcp":"Башня связи","place_cli":"Терминальная таверна","drawer_skills_title":"Кузница навыков","drawer_skills_hint":"Все навыки приложения. Черновики навыков, освоенных агентами, ждут здесь вашего одобрения.","skills_group_draft":"Черновики на одобрение","skills_group_custom":"Ваши","skills_group_builtin":"Встроенные","drawer_mcp_title":"Башня связи","drawer_mcp_hint":"Серверы MCP, доступные приложению. Антенна вращается, когда агент обращается к одному из них.","mcp_group_stdio":"Локальные (stdio)","mcp_group_http":"Удалённые (HTTP)","drawer_cli_title":"Терминальная таверна","drawer_cli_hint":"CLI для программирования и их аккаунты. Агент сидит здесь за терминалом, пока идёт сеанс программирования.","cli_group_connected":"Подключены","cli_group_installed":"Установлены, но не подключены","cli_group_missing":"Не установлены","place_comms":"Узел сообщений","place_desktop":"Пульт управления","place_web":"Смотровая башня","place_models":"Котельная","place_civic":"Ратуша","place_gallery":"Галерея","drawer_comms_title":"Узел сообщений","drawer_comms_hint":"Почта, чаты, контакты и звонки. Агент находится здесь, когда пишет человеку или коллеге по команде.","comms_group_mail":"Почта и чаты","comms_group_people":"Люди и звонки","drawer_desktop_title":"Пульт управления","drawer_desktop_hint":"Управление компьютером: нажатия, клавиши, окна и содержимое экрана. Агент находится здесь, когда работает на компьютере.","desktop_group_pointer":"Указатель и клавиши","desktop_group_screen":"Экран и окна","drawer_web_title":"Смотровая башня","drawer_web_hint":"Внешний мир: интернет-поиск и собственный браузер агента. Агент находится здесь, когда читает внешние материалы.","web_group_search":"Поиск и загрузка","web_group_browser":"Браузер агента","drawer_models_title":"Котельная","drawer_models_hint":"Здесь думает локальная модель. Агент находится здесь, пока работает его собственный мозг на устройстве.","drawer_models_body":"Агент с провайдером, которому не нужен ключ, работает на этом компьютере. Пока модель думает, фигурка стоит у котельной, а не у инструментов: сейчас идёт размышление, а не вызов инструмента.","drawer_civic_title":"Ратуша","drawer_civic_hint":"Комнаты и доска. Агент находится здесь, когда участвует в ограниченном обсуждении с другими.","drawer_civic_body":"Комната — ограниченный разговор между выбранными агентами: она открывается, обсуждение идёт и завершается. Все участники открытой комнаты стоят у ратуши до завершения. Доска показывает, над чем работает сообщество.","drawer_gallery_title":"Галерея","drawer_gallery_hint":"Готовые работы. Агент приносит сюда результат, как только завершает его.","drawer_gallery_body":"Каждый результат агента архивируется и отображается в полном размере в разделе «Артефакты»: страницы, диаграммы и изображения. Фигурка несколько секунд несёт сюда ящик, а затем возвращается к работе.","card_comms_does":"В узле сообщений агенты пишут другим: через почту, чаты, адресную книгу и телефон, а также обмениваются сообщениями между собой. Изоляторы на мачте светятся при передаче сообщения.","card_comms_how":"Подключите плагин почты или чата либо заполните адресную книгу. Агент с этими инструментами приходит сюда, когда пишет человеку или участнику команды.","card_desktop_does":"Пульт управления отвечает за действия на вашем компьютере: открытие приложений, нажатия, ввод текста, прокрутку, переключение окон и чтение экрана. Каждый такой инструмент помещает фигурку за это стекло.","card_desktop_how":"Разрешите агенту инструменты управления компьютером. Следите за рычагами: он управляет вашим настоящим компьютером, поэтому задайте подходящий предел разрешений.","card_web_does":"Смотровая башня следит за внешним миром: интернет-поиском и собственным браузером агента. Телескоп направлен в море, потому что все прочитанные материалы приходят из-за пределов острова.","card_web_how":"Для поиска нужен поисковый сервис; браузер устанавливается один раз для каждого агента. После этого оба работают без дополнительной настройки.","card_models_does":"В котельной думает модель на устройстве. Агент с локальным провайдером без ключа находится здесь, пока работает его мозг, вместо здания инструмента, который он сейчас не использует.","card_models_how":"Установите модель в разделе «Локальные модели» и укажите её в настройках провайдера агента. Данные не покидают компьютер.","card_civic_does":"В ратуше находятся комнаты: ограниченные обсуждения между выбранными агентами, которые открываются, проходят и завершаются. Все участники находятся здесь, пока комната открыта.","card_civic_how":"Откройте комнату с доски или поручите это координатору. Доска объявлений снаружи показывает текущую работу сообщества.","card_gallery_does":"В галерею попадают готовые работы. Как только агент передаёт результат, он приносит сюда ящик; страницы, диаграммы и изображения отображаются в приложении в полном размере.","card_gallery_how":"Ничего настраивать не нужно: каждый переданный результат архивируется автоматически и открывается в разделе «Артефакты».","drawer_foundry_body":"Новый агент создаётся здесь и выходит из этой двери к своему дому на кольцевой улице. Нажмите «Новый» на панели агентов, чтобы создать его; изменение аватара также происходит внутри.","place_market":"Рыночная площадь","place_hub":"Центр Jarvis","place_workshop":"Мастерская","place_archive":"Дом памяти","drawer_memory_title":"Дом памяти","drawer_memory_hint":"Общая память агентов: проверенные знания команды, личная память каждого агента и очередь на проверку. Агент приходит сюда, когда вспоминает или ищет сведения.","memory_search_placeholder":"Поиск в памяти…","memory_search_button":"Найти","memory_hits":"Результаты","memory_no_hits":"Ничего не найдено.","memory_shared":"Знания команды","memory_empty_shared":"Проверенных общих знаний пока нет. Предложения агентов попадают в очередь ниже.","memory_agents":"Память каждого агента","memory_notes":"Заметок: {count}","memory_nothing_remembered":"Пока ничего не запомнено.","memory_queue":"На проверке","memory_empty_queue":"Проверять нечего.","memory_promote":"Добавить в знания команды","memory_dismiss":"Проверено","memory_open_wiki":"Открыть вики","place_harbor":"Ворота гавани","place_lighthouse":"Маяк","place_gardens":"Сады","place_solar":"Солнечная электростанция","place_mine":"Шахта"}}'),_={society:e};export{_ as default,e as society};
